function saveResult(correct,answers,score){
 const s=JSON.parse(localStorage.getItem('mobiliza.results')||'{"games":0,"correct":0,"answers":0,"best":0,"streak":0}');
 s.games=(s.games||0)+1;s.correct=(s.correct||0)+correct;s.answers=(s.answers||0)+answers;s.best=Math.max(s.best||0,score);
 localStorage.setItem('mobiliza.results',JSON.stringify(s));
}

export function openCidade(dialog,host,onFinish){
 ensureCityCss();dialog.classList.add('city34dlg');dialog.addEventListener('close',()=>{dialog.classList.remove('city34dlg');if(timer)clearInterval(timer);if(simTimer)clearInterval(simTimer)},{once:true});
 let idx=0,done=new Set(),tries=new Map(),answers=0,score=0,finished=false,start=Date.now(),timer=null;
 let sound=localStorage.getItem('mobiliza.cidade.sound')!=='0',ctx=null,explore=false,simTimer=null,signalPhase='green',signalLeft=8;
 const cur=()=>MISSIONS[idx],secs=()=>Math.floor((Date.now()-start)/1000),best=()=>JSON.parse(localStorage.getItem('mobiliza.cidade.best')||'null');
 const audio=()=>{if(!sound)return null;try{const C=window.AudioContext||window.webkitAudioContext;if(!ctx)ctx=new C();if(ctx.state==='suspended')ctx.resume();return ctx}catch{return null}};
 const tone=(f,d=.07,t=0,type='sine',g=.035)=>{const c=audio();if(!c)return;const o=c.createOscillator(),v=c.createGain(),st=c.currentTime+t;o.type=type;o.frequency.setValueAtTime(f,st);v.gain.setValueAtTime(.0001,st);v.gain.exponentialRampToValueAtTime(g,st+.01);v.gain.exponentialRampToValueAtTime(.0001,st+d);o.connect(v);v.connect(c.destination);o.start(st);o.stop(st+d+.03)};
 const sounds={click:()=>tone(520,.045,0,'square',.02),ok:()=>{tone(523,.07);tone(659,.07,.07);tone(784,.14,.14)},no:()=>{tone(290,.08,0,'sawtooth',.025);tone(210,.12,.08,'sawtooth',.025)},mission:()=>{tone(660,.06);tone(880,.1,.07)},finish:()=>{tone(523,.08);tone(659,.08,.08);tone(784,.08,.16);tone(1046,.22,.24)}};
 const pts=n=>n<=1?500:n===2?350:200,attempt=i=>tries.get(i)||0,bestText=()=>best()?best().score+' pts • '+best().seconds+'s':'Sem recorde';

 const mapHtml=()=>'<div class="map realmap phase-'+signalPhase+'" id="cityMap">'+
 '<div class="route">📷 Cenário realista IA • Missões '+done.size+'/'+MISSIONS.length+'</div>'+
 '<div class="livebar"><span class="live-dot"></span><span id="liveText">Semáforo em tempo real</span><strong id="liveCount">'+signalLeft+'s</strong></div>'+
 '<div class="realtime-light"><i></i><i></i><i></i><span class="signal-count" id="signalCount">'+signalLeft+'</span></div>'+
 '<div class="simcar car1"></div><div class="simcar car2"></div><div class="simcar car3"></div><div class="simbus"></div><div class="simmoto"></div>'+
 '<div class="simped">🚶</div><div class="simcyclist">🚴</div>'+
 '<button class="poi p1" data-poi="faixa">?</button><button class="poi p2" data-poi="semaforo">?</button><button class="poi p3" data-poi="ciclovia">?</button><button class="poi p4" data-poi="onibus">?</button><button class="poi p5" data-poi="velocidade">?</button><button class="poi p6" data-poi="escola">?</button>'+
 '<div class="exploreBanner">🔎 Modo exploração: toque nos ? para conhecer a cidade</div>'+
 MISSIONS.map((m,i)=>{const pos=[[13,34],[35,32],[42,56],[62,18],[84,49],[88,75],[68,59]][i];return '<button class="hot '+(done.has(i)?'done':i===idx?'active':'lock')+'" data-hot="'+i+'" style="left:'+pos[0]+'%;top:'+pos[1]+'%">'+(done.has(i)?'✓':m.n)+'</button>'}).join('')+
 '<div class="avatar" style="left:calc('+([[13,34],[35,32],[42,56],[62,18],[84,49],[88,75],[68,59]][idx][0])+'% - 19px);top:calc('+([[13,34],[35,32],[42,56],[62,18],[84,49],[88,75],[68,59]][idx][1])+'% - 52px)">🧒</div></div>';
 const stepsHtml=()=>'<div class="steps">'+MISSIONS.map((m,i)=>'<div class="step '+(done.has(i)?'done':i===idx?'active':'')+'"><span>'+(done.has(i)?'✓':m.n)+'</span><div><strong>'+m.title+'</strong><small>'+m.role+' • '+m.place+'</small></div><small>'+(done.has(i)?'concluída':i===idx?'agora':'bloqueada')+'</small></div>').join('')+'</div><div class="cityMini">'+MISSIONS.map((m,i)=>'<div class="miniStep '+(done.has(i)?'done':i===idx?'active':'')+'">'+(done.has(i)?'✓':m.n)+'</div>').join('')+'</div>';

 function signalDuration(p){return p==='green'?8:p==='yellow'?3:7}
 function nextSignal(p){return p==='green'?'yellow':p==='yellow'?'red':'green'}
 function paintSignal(){
  const map=host.querySelector('#cityMap');if(!map)return;
  map.classList.remove('phase-green','phase-yellow','phase-red');map.classList.add('phase-'+signalPhase);
  const count=host.querySelector('#signalCount');if(count)count.textContent=signalLeft;
  const live=host.querySelector('#liveCount');if(live)live.textContent=signalLeft+'s';
  const txt=host.querySelector('#liveText');
  if(txt)txt.textContent=signalPhase==='green'?'Veículos em movimento • pedestres aguardam':signalPhase==='yellow'?'Atenção • transição do fluxo':'Veículos parados • travessia de pedestres';
 }
 function startSimulation(){
  if(simTimer)clearInterval(simTimer);
  paintSignal();
  simTimer=setInterval(()=>{signalLeft--;if(signalLeft<=0){signalPhase=nextSignal(signalPhase);signalLeft=signalDuration(signalPhase)}paintSignal()},1000);
 }
 function render(){
  const m=cur();
  host.innerHTML='<section class="game city34"><div class="hero"><img src="assets/games/cidade_mirim_realista_ai_v35.webp?v=35"><div><p>CIDADE MIRIM REAL • MISSÕES URBANAS</p><h2>Cidade realista: observe o trânsito acontecendo em tempo real</h2><small>Pedestre, ciclista, passageiro, condutor e agente mirim.</small></div></div><div class="bar"><div class="stats"><div class="stat"><span>✅ Missões</span><b id="cdone">'+done.size+'/'+MISSIONS.length+'</b></div><div class="stat"><span>⭐ Pontos</span><b id="cscore">'+score+'</b></div><div class="stat"><span>🎯 Respostas</span><b id="canswers">'+answers+'</b></div><div class="stat"><span>⏱ Tempo</span><b id="ctime">0s</b></div></div><div class="tools"><button class="tool" id="csound">'+(sound?'🔊':'🔇')+' Som</button><button class="tool" id="cexplore">🔎 Explorar</button><button class="tool" id="crules">❔ Como jogar</button><button class="tool" id="creset">↻ Reiniciar</button></div></div><div class="main"><div class="mapbox">'+mapHtml()+'</div><aside class="panel"><div class="mhead"><img src="'+m.img+'"><div><span class="role">'+m.role+'</span><h3>Missão '+m.n+': '+m.title+'</h3><p>📍 '+m.place+'</p></div></div><div class="mbody"><h4>Rota do Agente Mirim</h4><p>Conclua a missão atual para liberar o próximo ponto.</p>'+stepsHtml()+'</div><div class="actions"><button class="start" id="cstart">▶ INICIAR MISSÃO '+m.n+'</button><button class="loc" id="clocate">📍 Localizar</button></div></aside></div><div class="foot"><div class="hint">💡 <strong>Clique no ponto amarelo '+m.n+' ou em “Iniciar missão”.</strong></div><div class="best"><span>🏆 Melhor</span><strong>'+bestText()+'</strong></div></div><div class="overlay" id="coverlay"></div></section>';
  bind();startTimer();startSimulation();
 }
 function hud(){const t=host.querySelector('#ctime');if(t)t.textContent=secs()+'s';const d=host.querySelector('#cdone');if(d)d.textContent=done.size+'/'+MISSIONS.length;const sc=host.querySelector('#cscore');if(sc)sc.textContent=score;const a=host.querySelector('#canswers');if(a)a.textContent=answers}
 function startTimer(){if(timer)clearInterval(timer);hud();timer=setInterval(()=>{if(!finished)hud()},500)}
 function overlay(html){const o=host.querySelector('#coverlay');o.className='overlay show';o.innerHTML=html;return o}
 function close(){const o=host.querySelector('#coverlay');if(o){o.className='overlay';o.innerHTML=''}}
 function bind(){
  host.querySelector('#cstart').onclick=()=>openMission(idx);
  host.querySelector('#clocate').onclick=()=>{sounds.click();host.querySelector('[data-hot="'+idx+'"]')?.animate([{transform:'translate(-50%,-50%) scale(1)'},{transform:'translate(-50%,-50%) scale(1.3)'},{transform:'translate(-50%,-50%) scale(1)'}],{duration:650})};
  host.querySelectorAll('[data-hot]').forEach(b=>b.onclick=()=>{const i=+b.dataset.hot;if(i===idx&&!done.has(i))openMission(i)});
  host.querySelector('#csound').onclick=()=>{sound=!sound;localStorage.setItem('mobiliza.cidade.sound',sound?'1':'0');if(sound)sounds.click();host.querySelector('#csound').textContent=(sound?'🔊':'🔇')+' Som'};
  host.querySelector('#cexplore').onclick=()=>{explore=!explore;sounds.click();const root=host.querySelector('.city34');root?.classList.toggle('explore',explore);host.querySelector('#cexplore').textContent=explore?'✕ Sair da exploração':'🔎 Explorar';};
  host.querySelectorAll('[data-poi]').forEach(b=>b.onclick=()=>{if(explore)showPoi(b.dataset.poi)});
  host.querySelector('#crules').onclick=rules;host.querySelector('#creset').onclick=confirmReset;
 }
 function showPoi(key){
  const info={
    faixa:['Faixa de pedestres','🚶','É um ponto de travessia sinalizado. O pedestre deve observar o trânsito e só atravessar quando houver condição segura.'],
    semaforo:['Semáforo','🚦','Organiza movimentos conflitantes. Atenção às cores e aos demais usuários continua essencial.'],
    ciclovia:['Espaço cicloviário','🚲','A separação visual do espaço de circulação ajuda a organizar a convivência entre modos.'],
    onibus:['Ponto de ônibus','🚌','Embarque e desembarque exigem atenção ao fluxo de pedestres e à aproximação de veículos.'],
    velocidade:['Velocidade regulamentada','40','A sinalização informa o limite daquele trecho. Próximo a áreas sensíveis, atenção deve ser redobrada.'],
    escola:['Área escolar','🏫','Há circulação intensa de crianças e responsáveis. Reduza a velocidade, respeite a faixa e mantenha máxima atenção.']
  }[key];
  if(!info)return;
  const o=overlay('<div class="modal"><p class="eye">MODO EXPLORAÇÃO</p><h3>'+info[1]+' '+info[0]+'</h3><div class="feedback"><p>'+info[2]+'</p></div><div class="fa"><button class="btn primary" id="cpoiok">Continuar explorando</button></div></div>');
  o.querySelector('#cpoiok').onclick=close;
 }
 function rules(){sounds.click();const o=overlay('<div class="modal"><div class="mh"><img src="assets/games/cidade_mirim_realista_ai_v35.webp?v=35"><div><p class="eye">COMO JOGAR</p><h3>Complete a rota da Cidade Mirim</h3></div></div><p class="question">Observe uma cidade realista funcionando: veículos circulam, o semáforo alterna fases e pedestres/ciclistas se movimentam. Percorra 7 pontos e resolva situações de convivência no trânsito.</p><div class="feedback"><p>1. Siga o ponto amarelo no mapa.</p><p>2. Leia a situação e escolha uma alternativa.</p><p>3. Se errar, aprenda com o feedback e tente novamente.</p><p>4. Quanto menos tentativas, maior a pontuação.</p><p>5. A próxima missão é liberada após o acerto.</p></div><div class="fa"><button class="btn primary" id="cok">Entendi</button></div></div>');o.querySelector('#cok').onclick=close}
 function confirmReset(){const o=overlay('<div class="modal"><p class="eye">REINICIAR</p><h3>Começar a rota novamente?</h3><p class="question">Missões, pontos, tentativas e tempo serão zerados.</p><div class="fa"><button class="btn ghost" id="cno">Cancelar</button><button class="btn primary" id="cyes">Reiniciar</button></div></div>');o.querySelector('#cno').onclick=close;o.querySelector('#cyes').onclick=reset}
 function openMission(i){
  if(i!==idx||done.has(i)||finished)return;sounds.mission();const m=MISSIONS[i],used=attempt(i);
  const o=overlay('<div class="modal"><div class="mh"><img src="'+m.img+'"><div><p class="eye">MISSÃO '+m.n+' DE '+MISSIONS.length+' • '+m.role+'</p><h3>'+m.title+'</h3></div></div><p class="question">'+m.q+'</p><div class="agrid">'+m.opts.map((x,n)=>'<button class="ans" data-a="'+n+'"><b>'+String.fromCharCode(65+n)+'</b><span>'+x+'</span></button>').join('')+'</div><div id="cfb">'+(used?'<div class="feedback"><strong>💡 Tentativa '+(used+1)+'</strong><p>Use o que aprendeu e escolha novamente.</p></div>':'')+'</div></div>');
  o.querySelectorAll('[data-a]').forEach(b=>b.onclick=()=>answerMission(i,+b.dataset.a,o));
 }
 function answerMission(i,picked,o){
  const m=MISSIONS[i],n=attempt(i)+1;tries.set(i,n);answers++;hud();const bs=[...o.querySelectorAll('[data-a]')];bs.forEach(b=>b.disabled=true);
  if(picked!==m.ok){sounds.no();bs[picked].classList.add('wrong');bs[m.ok].classList.add('correct');const fb=o.querySelector('#cfb');fb.innerHTML='<div class="feedback"><strong>💡 Vamos aprender</strong><p>'+m.why+'</p><div class="fa"><button class="btn primary" id="ctry">Tentar novamente</button></div></div>';fb.querySelector('#ctry').onclick=()=>{close();setTimeout(()=>openMission(i),120)};return}
  sounds.ok();bs[m.ok].classList.add('correct');const gain=pts(n);score+=gain;done.add(i);hud();const fb=o.querySelector('#cfb');fb.innerHTML='<div class="feedback"><strong>✅ Missão cumprida! +'+gain+' pontos</strong><p>'+m.why+'</p><div class="fa"><button class="btn primary" id="ccont">'+(i===MISSIONS.length-1?'Ver resultado':'Continuar rota')+'</button></div></div>';fb.querySelector('#ccont').onclick=()=>{close();if(i===MISSIONS.length-1){setTimeout(finish,150);return}idx=i+1;setTimeout(render,220)}
 }
 function finish(){
  if(finished)return;finished=true;if(timer)clearInterval(timer);if(simTimer)clearInterval(simTimer);sounds.finish();const seconds=secs(),rec={score,seconds,answers,date:new Date().toISOString()},old=best();if(!old||score>old.score||(score===old.score&&seconds<old.seconds))localStorage.setItem('mobiliza.cidade.best',JSON.stringify(rec));saveResult(MISSIONS.length,answers,score);onFinish?.();
  host.innerHTML='<section class="cityResult"><div class="rh"><img src="assets/games/cidade_mirim_realista_ai_v35.webp?v=35"><div><p>CIDADE MIRIM • RESULTADO</p><h2>Rota concluída!</h2></div><div class="medal">🏅</div></div><div class="rs"><div class="rstat"><span>✅ Missões</span><b>'+MISSIONS.length+'/'+MISSIONS.length+'</b></div><div class="rstat"><span>🎯 Respostas</span><b>'+answers+'</b></div><div class="rstat"><span>⏱ Tempo</span><b>'+seconds+'s</b></div><div class="rstat"><span>⭐ Pontos</span><b>'+score+'</b></div></div><div class="badges">'+MISSIONS.map((m,i)=>'<div class="badge"><img src="'+m.img+'"><div><strong>✅ '+m.title+'</strong><small>'+m.role+' • '+m.place+' • '+pts(attempt(i))+' pts</small></div></div>').join('')+'</div><div class="ra"><button class="btn primary" id="cagain">↻ Jogar novamente</button><button class="btn ghost" id="cclose">Encerrar</button></div></section>';
  host.querySelector('#cagain').onclick=reset;host.querySelector('#cclose').onclick=()=>dialog.close();
 }
 function reset(){if(timer)clearInterval(timer);if(simTimer)clearInterval(simTimer);idx=0;done=new Set();tries=new Map();answers=0;score=0;finished=false;explore=false;signalPhase='green';signalLeft=8;start=Date.now();render()}
 render();if(!dialog.open)dialog.showModal();
}
